  "type": "numeric",
  "difficulty": "basic",
  "question": "$80\\,^\\circ\\mathrm{C}$ の水 $100\\,\\mathrm{g}$ と $20\\,^\\circ\\mathrm{C}$ の水 $300\\,\\mathrm{g}$ を混ぜた。熱の出入りが外部と無いとして、全体が同じ温度になったときの温度は何 $^\\circ\\mathrm{C}$ か。",
