  "difficulty": "standard",
  "question": "$0\\,^\\circ\\mathrm{C}$ の氷 $50\\,\\mathrm{g}$ をすべて $0\\,^\\circ\\mathrm{C}$ の水にするのに必要な熱量は何 $\\mathrm{J}$ か。氷の融解熱を $3.3\\times 10^2\\,\\mathrm{J/g}$ とする。",
