  "difficulty": "standard",
  "question": "シリンダー内の気体に $500\\,\\mathrm{J}$ の熱を与えたところ、気体は膨張してピストンに $200\\,\\mathrm{J}$ の仕事をした。気体の内部エネルギーの増加は何 $\\mathrm{J}$ か。",
