  "difficulty": "basic",
  "question": "$2.0\\,\\mathrm{C}$ の正電荷を、電位 $3.0\\,\\mathrm{V}$ の点から $8.0\\,\\mathrm{V}$ の点までゆっくり運んだ。外力がした仕事は何 $\\mathrm{J}$ か。",
