   "$4.0\\,\\Omega$ にかかる電圧は $V = IR = 2.0\\times 4.0 = 8.0\\,\\mathrm{V}$。残り $4.0\\,\\mathrm{V}$ が $2.0\\,\\Omega$ 側。合計 $12\\,\\mathrm{V}$ で第2法則が成り立つ。",
