   "$E_n \\ge E_0$ かつ $\\sum|c_n|^2 = 1$ なので、$\\langle H\\rangle \\ge E_0\\sum|c_n|^2 = E_0$。等号は $|\\phi\\rangle$ が基底状態に一致するときのみ。",
