  "question": "低エネルギー散乱で $s$ 波（$l=0$）のみが効き、位相のずれが $\\delta_0 = 30^\\circ$、波数が $k = 1.0\\,\\mathrm{fm}^{-1}$ であった。全散乱断面積は何 $\\mathrm{fm^2}$ か。",
