   "$z=i$ での留数は $\\dfrac{1}{z+i}\\Big|_{z=i} = \\dfrac{1}{2i}$。半円上の寄与は半径 $\\to\\infty$ で消える（被積分関数が $1/R^2$ で減衰）。",
